using System.Linq;
int[] nr = {1, 5, 8};
var res = from n in nr where n > 4 select n;
Console.WriteLine(res.Count());

using System.Linq;
int[] nr = {1, 5, 8};
Console.WriteLine(nr.Where(n => n > 4).Sum());

using System.Linq;
int[] nr = {3, 1, 2};
Console.WriteLine(nr.OrderBy(n => n).First());

using System.Linq;
int[] nr = {1, 2};
Console.WriteLine(nr.Any(n => n > 1));
